/* From Uiverse.io by Salahkarrar  - Tags: button, hover, light, click */
.__UIV_SCOPE__ .wave-button {
  background-color: #eaf2f8;
  border: 2px solid #ddd;
  color: #000;
  padding: 15px 30px;
  cursor: pointer;
  border-radius: 5px;
  font-size: 16px;
  position: relative;
  overflow: hidden;
  transition: all 0.3s ease;
}

.__UIV_SCOPE__ .wave-button:before {
  content: "";
  position: absolute;
  right: 0;
  bottom: 0;
  width: 0;
  height: 0px;
  background-color: rebeccapurple;
  box-shadow: 0 0 40px rgba(255, 255, 255, 0.4);
  transition: all 0.5s ease;
}

.__UIV_SCOPE__ .wave-button:hover {
  background-color: #ddd;
  border-color: rebeccapurple;
}

.__UIV_SCOPE__ .wave-button:hover:before {
  height: 5%;
  width: 100%;
  animation: wave-animation 0.5s linear forwards;
}

@keyframes wave-animation {
  to {
    right: 100%;
  }
}

.__UIV_SCOPE__ .wave-button span {
  position: relative;
  z-index: 1;
}
